insert into public.productos
  (nombre_es, nombre_eu, descripcion_es, descripcion_eu, origen_es, origen_eu, precio, categoria, subcategoria, imagen_url, estado, disponible, orden)
values
  ('Anchoa', 'Antxoa', 'Pescado azul de sabor intenso. Fresca, perfecta para boquerones, fritura o en vinagre.', 'Zapore biziko arrain urdina. Freskoa, bokartetarako, frijitzerako edo ozpinetarako ezin hobea.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 10€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/3833c4e4-8916-4d6f-ada5-a96f62d954fb.jpg', 'available', true, 0),
  ('Sardina', 'Sardina', 'La joya del Cantábrico en verano. Carne sabrosa y jugosa, ideal a la brasa.', 'Kantauriko izarra udan. Haragi zaporetsu eta zukutsua, parrilan egiteko aparta.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 8€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/7aa7ac2d-e110-4e4f-abe5-249b66d5386c.jpg', 'available', true, 1),
  ('Txitxarrito', 'Txitxarritoa', 'Jurel pequeño de sabor delicado. Perfecto para fritura, en escabeche o a la plancha.', 'Zapore fineko txitxarro txikia. Frijitzerako, ozpinetarako edo plantxarako perfektua.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 9€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/5fd07b46-d413-4ca4-ab7b-f9a729b4866c.jpg', 'available', true, 2),
  ('Txitxarro', 'Txitxarroa', 'Jurel de buen tamaño, carne firme y sabrosa. Ideal a la plancha, al horno o en guisos.', 'Tamaina oneko txitxarroa, haragi trinko eta zaporetsua. Plantxan, labean edo gisatuetan bikaina.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 11€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/c63a88e9-fc64-485d-8b43-4ade4b94f2e2.jpg', 'available', true, 3),
  ('Verdel', 'Berdela', 'El tesoro de la primavera. Sabor potente, carne jugosa y un precio inmejorable.', 'Udaberriko altxorra. Zapore indartsua, haragi zukutsua eta prezio ezin hobea.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 12€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/09f9f281-c8a4-4532-96d9-d1e6ee9bad74.jpg', 'seasonal', true, 4),
  ('Salmonete', 'Salmonetea', 'Pescado de roca de sabor intenso y color vibrante. Pequeño pero extraordinario.', 'Haitzetako arraina, zapore bizi eta kolore bizikoa. Txikia baina bikaina.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 20€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/0f2093c5-1587-4a71-a8b0-e666ff7baf3c.jpg', 'seasonal', true, 5),
  ('Salmón', 'Izokina', 'Salmón fresco de alta calidad. Versátil, sabroso y perfecto para cualquier preparación.', 'Kalitate handiko izokin freskoa. Anitza, zaporetsua eta edozein prestaketarako ezin hobea.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 18€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/5b7eba69-8715-4806-abd1-8903ac072100.jpg', 'available', true, 6),
  ('Bonito del Norte', 'Iparraldeko Hegaluzea', 'La estrella del verano. En lomos frescos, en rodajas o para un marmitako tradicional.', 'Udako izarra. Xerra freskoetan, zatitan edo ohiko marmitakorako.', 'Lonja de Getaria', 'Getariako lonja', 'Desde 18€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/eec380c4-fa2c-4d87-b3aa-3645b9f115e8.jpg', 'seasonal', true, 7),
  ('Atún', 'Hegaluzea', 'Atún rojo de calidad premium. Carne intensa y sabrosa para los paladares más exigentes.', 'Kalitate bikaineko hegalabur gorria. Haragi bizi eta zaporetsua zapore zorrotzenentzat.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 25€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/c2cd17b7-1302-488b-aa85-8b2f10ab7623.jpg', 'premium', true, 8),
  ('Zapatero', 'Zapataria', 'Pescado azul de carne prieta y sabrosa. Una joya por descubrir del Cantábrico.', 'Haragi trinko eta zaporetsuko arrain urdina. Kantauriko aurkitu beharreko altxorra.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 14€/kg', 'pescado', 'azul', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/0c93300b-7a92-4314-8679-c123fa5717bf.jpg', 'new', true, 9),
  ('Lubina', 'Lupia', 'Pescado semigraso de sabor delicado. Versátil: al horno, a la sal, a la plancha o en ceviche.', 'Zapore fineko arrain erdi-gantza. Anitza: labean, gatzetan, plantxan edo cevichean.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 28€/kg', 'pescado', 'semigraso', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/1f4dee58-b941-422b-b8ae-f3fdd30ba15f.jpg', 'available', true, 10),
  ('Dorada', 'Dorada', 'Carne blanca y sabrosa con un toque marino. Perfecta al horno con verduras o a la espalda.', 'Haragi zuri eta zaporetsua itsas ukituarekin. Labean barazkiekin edo bizkaitar erara bikaina.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 22€/kg', 'pescado', 'semigraso', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/373cdce7-8f36-4be5-8035-4ed67316ba33.jpg', 'available', true, 11),
  ('Filete de Gallineta', 'Gallineta Xerra', 'Filetes limpios de gallineta. Carne blanca firme y sin espinas, ideal para guisos marineros.', 'Gallineta xerra garbiak. Haragi zuri trinko eta hezurrik gabea, itsaski gisatuetarako bikaina.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 30€/kg', 'pescado', 'filetes_lomos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/4adc23c3-ab4c-4849-a5cc-232718fd057a.jpg', 'available', true, 12),
  ('Filete de Bakalao al Punto de Sal', 'Bakailao Xerra Gatz Puntuan', 'Filetes de bacalao en su punto justo de sal. Listo para cocinar, perfecto al pil-pil o a la vizcaína.', 'Bakailao xerrak gatz neurri egokian. Kozinatzeko prest, pil-pilean edo bizkaitar erara perfektua.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 28€/kg', 'pescado', 'filetes_lomos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/d1a54d79-a268-4c13-a01b-f28f4e497097.jpg', 'premium', true, 13),
  ('Filete de Perca', 'Perka Xerra', 'Filetes de perca frescos, carne blanca y delicada. Perfectos para rebozar o a la plancha.', 'Perka xerra freskoak, haragi zuri eta delikatua. Frijitzerako edo plantxarako perfektuak.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 20€/kg', 'pescado', 'filetes_lomos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/945299ba-d0c1-49ac-93bd-09f520332093.jpg', 'new', true, 14),
  ('Lomo de Bakalao Desalado', 'Bakailao Lomo Gatzgabetua', 'Lomos gruesos de bacalao desalado, listos para cocinar. Calidad premium para los platos más exigentes.', 'Bakailao lomo lodi gatzgabetuak, prestatzeko prest. Kalitate bikaina plater zorrotzenentzat.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 32€/kg', 'pescado', 'filetes_lomos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/01610f59-1a46-4b46-9313-6312ec4fb57a.jpg', 'premium', true, 15),
  ('Merluza Bolanta', 'Legatz Bolanta', 'Merluza capturada con arte de volanta. Carne blanca y tersa, calidad excepcional.', 'Bolanta artearekin harrapatutako legatza. Haragi zuri eta tinkoa, kalitate paregabea.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 22€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/c1ec4132-2cde-460b-8971-583856319564.jpg', 'new', true, 16),
  ('Merluza Pintxo', 'Pintxo Legatza', 'Merluza de pincho del Cantábrico, la reina de nuestras costas. Carne prieta y sabor inconfundible.', 'Kantauriko pintxo-legatza, gure kostaldeko erregina. Haragi trinko eta zapore ahaztezina.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 30€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/3931eb6c-9185-426e-8091-0e465a48c0db.jpg', 'premium', true, 17),
  ('Bakalao Fresco', 'Bakailao Freskoa', 'Bacalao fresco del Atlántico Norte. Carne blanca y jugosa, versátil en cocina.', 'Ipar Atlantikoko bakailao freskoa. Haragi zuri eta zukutsua, sukaldean anitza.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 26€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/99585c3d-8520-450e-87d1-d2a00fe31a94.jpg', 'available', true, 18),
  ('Kokotxa de Bakalao', 'Bakailao Kokotxa', 'La parte más gelatinosa y sabrosa del bacalao. Un manjar de la cocina vasca tradicional.', 'Bakailaoaren zatirik gelatinotsu eta zaporetsuena. Euskal sukaldaritza tradizionalaren jaki preziatua.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 45€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/fe9a774a-308c-46f7-8b8e-add5aa1c3d8b.jpg', 'premium', true, 19),
  ('Lirio', 'Lirioa', 'Pescado blanco de carne fina y delicada. Similar a la merluza pero más económico. Ideal para rebozar.', 'Haragi fin eta delikatuko arrain zuria. Legatzaren antzekoa baina merkeagoa. Frijitzerako ezin hobea.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 16€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/18781853-c55c-475f-b783-91b723075f22.jpg', 'available', true, 20),
  ('Karioka', 'Karioka', 'Pescado blanco de temporada, carne suave y digestiva. Perfecto para niños y dietas ligeras.', 'Sasoiko arrain zuria, haragi leun eta digestiboa. Haurrentzako eta dieta arinetarako perfektua.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 15€/kg', 'pescado', 'merluza_bakalao', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/d4f985ab-818c-42e8-89f4-b87a272dd2e2.jpg', 'new', true, 21),
  ('Kabratxo', 'Kabratxoa', 'Cabracho de roca, el secreto del auténtico pastel de cabracho. Carne firme y sabrosa.', 'Haitzetako kabratxoa, benetako kabratxo pastelaren sekretua. Haragi trinko eta zaporetsua.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 22€/kg', 'pescado', 'roca', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/be13a105-ce47-49e0-b2c6-b2b56712ed5e.jpg', 'available', true, 22),
  ('Itxaskabra', 'Itsaskabra', 'Pescado de roca de carne exquisita. Ideal para calderetas, suquets y guisos marineros tradicionales.', 'Haragi bikaineko haitzetako arraina. Kaldareta, suquet eta itsaski gisatu tradizionaletarako ezin hobea.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 24€/kg', 'pescado', 'roca', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/b05432de-199a-435a-9f0c-1946a446772f.jpg', 'new', true, 23),
  ('Congrio', 'Itsas Aingira', 'Carne firme y sin espinas, perfecta para guisos, zarzuelas y preparaciones marineras.', 'Haragi trinko eta hezurrik gabea, gisatu, zarzuela eta itsaski prestaketetarako perfektua.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 18€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/db89e9e7-6f9b-4038-9646-05bf11f12fb7.jpg', 'available', true, 24),
  ('Gallito', 'Oilar Txikia', 'Pescado de roca con carne firme y sabrosa. Excelente para caldos, sopas de pescado y guisos.', 'Haragi trinko eta zaporetsuko haitzetako arraina. Arrain salda, zopa eta gisatuetarako bikaina.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 14€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/0b290cc6-0e24-4ebe-b2e4-de19490fa0d6.jpg', 'available', true, 25),
  ('Gallo', 'Oilarra', 'Pescado plano de carne blanca y fina. Perfecto a la plancha, al horno o en salsa verde.', 'Haragi zuri eta fineko arrain laua. Plantxan, labean edo saltsa berdean perfektua.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 20€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/7b660273-44dc-4d15-bc1f-934f092708ac.jpg', 'available', true, 26),
  ('Faneca', 'Faneka', 'Pescado blanco de carne delicada. Muy apreciado en el Cantábrico para fritura y rebozados.', 'Haragi delikatuko arrain zuria. Kantaurin oso estimatua frijitzerako eta birrineztatzerako.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 12€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/b0a3aa39-db00-4cfc-9649-e11daf581a1a.jpg', 'new', true, 27),
  ('Pescadilla', 'Peskadilla', 'Merluza joven de carne tierna y blanca. Perfecta para fritura, rebozada o en salsa verde.', 'Haragi samur eta zuriko legatz gaztea. Frijitzerako, birrineztatuta edo saltsa berdean perfektua.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 15€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/10229fd2-1197-44c5-9eeb-1a3c48788200.jpg', 'available', true, 28),
  ('Lotxa', 'Lotxa', 'Pescado blanco de la familia del bacalao, carne suave y sabrosa. Ideal para guisos tradicionales.', 'Bakailaoaren familiako arrain zuria, haragi leun eta zaporetsua. Gisatu tradizionaletarako bikaina.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 13€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/4642d5ee-064e-4e71-8bed-cc716ef63f47.jpg', 'available', true, 29),
  ('Rape / Sapito', 'Zapoa / Sapitoa', 'Rape fresco entero. Carne firme y sin espinas, perfecto para guisos y zarzuelas marineras.', 'Zapo fresko osoa. Haragi trinko eta hezurrik gabea, gisatu eta itsaski zarzueletarako perfektua.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 26€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/5c1d4b69-e339-4df1-96ce-229c235640b2.jpg', 'premium', true, 30),
  ('Cola de Rape', 'Zapo Isatsa', 'Colas de rape limpias, la parte más noble. Carne blanca prieta y sin una sola espina. Para platos de categoría.', 'Zapo isats garbiak, zatirik nobleena. Haragi zuri trinko eta hezurrik gabea. Maila altuko plateretarako.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 32€/kg', 'pescado', 'blanco', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/e02cdcb8-4fe2-4cc7-84d0-37fe01b2cd5c.jpg', 'premium', true, 31),
  ('Jibión / Txipirón', 'Jiboia / Txipiroia', 'Calamares y chipirones frescos de potera. Limpios, tiernos y listos para la plancha o fritura.', 'Potera txipiroi eta txibia freskoak. Garbiak, samurrak eta plantxarako edo frijitzerako prest.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 18€/kg', 'pescado', 'cefalopodos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/029185f3-781b-479f-b209-2352f4d9e205.jpg', 'available', true, 32),
  ('Begihandi', 'Begihandia', 'Calamares grandes de calidad premium. Perfectos a la plancha, en su tinta o rellenos.', 'Kalitate bikaineko txipiroi handiak. Plantxan, bere tintan edo beteta perfektuak.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 20€/kg', 'pescado', 'cefalopodos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/7e63c81c-a44a-4a1c-86a3-70a8a7555e69.jpg', 'new', true, 33),
  ('Sepia', 'Txibia', 'Sepia fresca de gran tamaño. Carne tierna y sabrosa, ideal a la plancha con ajo y perejil.', 'Tamaina handiko txibia freskoa. Haragi samur eta zaporetsua, plantxan baratxuri eta perrexilarekin bikaina.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 22€/kg', 'pescado', 'cefalopodos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/ddeb8642-915a-42de-aa66-c1a67e2f7b9e.jpg', 'available', true, 34),
  ('Pulpo Fresco', 'Olagarro Freskoa', 'Pulpo fresco del Cantábrico. Textura inigualable para el auténtico pulpo a la gallega o a la brasa.', 'Kantauriko olagarro freskoa. Ehundura paregabea benetako olagarro galiziar erara edo parrilan egiteko.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 24€/kg', 'pescado', 'cefalopodos', 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/96647983-fc5a-4ea0-b031-38a6456e3e32.jpg', 'premium', true, 35),
  ('Rodaballo', 'Erreboiloa', 'Un pescado excepcional de carne prieta y sabrosa. Ideal para ocasiones especiales y celebraciones.', 'Haragi sendo eta zaporetsuko arrain bikaina. Momentu berezi eta ospakizunetarako egokia.', 'Lonja de Santurtzi', 'Santurtziko lonja', 'Desde 35€/kg', 'especial', null, 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/d7d89068-4abb-484d-b455-85614514881a.jpg', 'premium', true, 36),
  ('Besugo', 'Bisigua', 'El rey de la parrilla y el horno. Carne blanca, fina y sabrosa. Un clásico de nuestras lonjas.', 'Parrilako eta labeko erregea. Haragi zuri, fin eta zaporetsua. Gure lonjetako klasikoa.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 32€/kg', 'especial', null, 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/097ad79a-0197-489d-980b-a6300acd3cf5.jpg', 'premium', true, 37),
  ('Pargo', 'Pargoa', 'Pescado premium de carne firme y sabor delicado. Muy apreciado en la alta cocina mediterránea.', 'Haragi trinko eta zapore fineko bikaineko arraina. Goi sukaldaritza mediterraneoan oso estimatua.', 'Lonja de Bermeo', 'Bermeoko lonja', 'Desde 30€/kg', 'especial', null, 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/7c55b864-c4d1-418d-8378-08bd27874311.jpg', 'premium', true, 38),
  ('Lubina de Calibre', 'Kalibreko Lupia', 'Lubina salvaje de gran tamaño. Piezas seleccionadas para los paladares más exigentes.', 'Tamaina handiko lupia basatia. Ahosabai zorrotzenentzako aukeratutako piezak.', 'Lonja de Ondarroa', 'Ondarroako lonja', 'Desde 36€/kg', 'especial', null, 'https://ukhfaphloxlszomccgde.supabase.co/storage/v1/object/public/pescados-mariscos-arrantza/catalogo/4cd41f79-65ba-4fa1-aadd-d27e80ce48ef.jpg', 'premium', true, 39),
